103	    @Transactional
104	    public OrderResponse createOrder(UUID memberId, CreateOrderRequest request, String idempotencyKey, String ipAddress) {
105	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
106	            throw new ApiException(HttpStatus.BAD_REQUEST, "IDEMPOTENCY_KEY_REQUIRED", "X-Idempotency-Key header is required");
107	        }
108	
109	        Optional<Order> existingByIdempotency = orderRepository.findByIdempotencyKey(idempotencyKey);
110	        if (existingByIdempotency.isPresent()) {
111	            return toOrderResponse(existingByIdempotency.get());
112	        }
113	
114	        User member = userRepository.findById(memberId)
115	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "USER_NOT_FOUND", "Member was not found"));
116	
117	        Map<UUID, Integer> quantitiesByListing = collapseQuantities(request.items());
118	        Map<UUID, Listing> listings = loadListings(quantitiesByListing.keySet());
119	
120	        Warehouse warehouse = chooseFulfillmentWarehouse(quantitiesByListing, request);
121	        List<InventoryRecord> lockedInventories = inventoryService.lockInventoriesByWarehouseAndListings(
122	            warehouse.getId(),
123	            new ArrayList<>(quantitiesByListing.keySet())
124	        );
125	
126	        Map<UUID, InventoryRecord> inventoryByListing = lockedInventories.stream()
127	            .collect(Collectors.toMap(ir -> ir.getListing().getId(), Function.identity()));
128	
129	        List<Map<String, Object>> unavailableItems = new ArrayList<>();
130	        for (Map.Entry<UUID, Integer> entry : quantitiesByListing.entrySet()) {
131	            InventoryRecord inventory = inventoryByListing.get(entry.getKey());
132	            int available = inventory == null ? 0 : inventory.getAvailableQty();
133	            if (available < entry.getValue()) {
134	                unavailableItems.add(Map.of(
135	                    "listingId", entry.getKey(),
136	                    "requestedQty", entry.getValue(),
137	                    "availableQty", available
138	                ));
139	            }
140	        }
141	        if (!unavailableItems.isEmpty()) {
142	            throw new ApiException(
143	                HttpStatus.CONFLICT,
144	                "STOCK_UNAVAILABLE",
145	                "Insufficient stock for one or more items",
146	                Map.of("unavailableItems", unavailableItems)
147	            );
148	        }
149	
150	        Membership membership = membershipRepository.findByUser_Id(memberId)
151	            .orElseThrow(() -> new ApiException(HttpStatus.BAD_REQUEST, "MEMBERSHIP_NOT_FOUND", "Membership record not found for member"));
152	        List<BenefitPackage> tierBenefits = benefitPackageRepository.findByTier_Id(membership.getTier().getId());
153	
154	        BigDecimal totalAmount = BigDecimal.ZERO;
155	        BigDecimal discountAmount = BigDecimal.ZERO;
156	        Map<UUID, BigDecimal> appliedBenefitTotals = new LinkedHashMap<>();
157	        List<OrderItemDraft> drafts = new ArrayList<>();
158	
159	        for (Map.Entry<UUID, Integer> entry : quantitiesByListing.entrySet()) {
160	            Listing listing = listings.get(entry.getKey());
161	            int quantity = entry.getValue();
162	            BigDecimal lineBase = listing.getPrice().multiply(BigDecimal.valueOf(quantity));
163	            totalAmount = totalAmount.add(lineBase);
164	
165	            List<BenefitPackage> applicable = tierBenefits.stream()
166	                .filter(bp -> isBenefitApplicable(bp, listing))
167	                .toList();
168	            List<BenefitPackage> selected = benefitEvaluationService.selectApplicableBenefits(applicable);
169	
170	            BenefitPackage appliedPriceBenefit = selected.stream()
171	                .filter(bp -> bp.getType() == BenefitType.EXCLUSIVE_PRICE || bp.getType() == BenefitType.PERCENTAGE_DISCOUNT)
172	                .findFirst()
173	                .orElse(null);
174	
175	            BigDecimal lineDiscount = BigDecimal.ZERO;
176	            if (appliedPriceBenefit != null) {
177	                if (appliedPriceBenefit.getType() == BenefitType.EXCLUSIVE_PRICE) {
178	                    BigDecimal lineExclusive = appliedPriceBenefit.getValue().multiply(BigDecimal.valueOf(quantity));
179	                    lineDiscount = lineBase.subtract(lineExclusive).max(BigDecimal.ZERO);
180	                } else if (appliedPriceBenefit.getType() == BenefitType.PERCENTAGE_DISCOUNT) {
181	                    lineDiscount = lineBase.multiply(appliedPriceBenefit.getValue())
182	                        .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
183	                }
184	                appliedBenefitTotals.merge(appliedPriceBenefit.getId(), lineDiscount, BigDecimal::add);
185	            }
186	
187	            discountAmount = discountAmount.add(lineDiscount);
188	            drafts.add(new OrderItemDraft(listing, quantity, appliedPriceBenefit));
189	        }
190	
191	        BigDecimal finalAmount = totalAmount.subtract(discountAmount).max(BigDecimal.ZERO).setScale(2, RoundingMode.HALF_UP);
192	
193	        for (Map.Entry<UUID, Integer> entry : quantitiesByListing.entrySet()) {
194	            InventoryRecord inventory = inventoryByListing.get(entry.getKey());
195	            int qty = entry.getValue();
196	            inventory.setAvailableQty(inventory.getAvailableQty() - qty);
197	            inventory.setReservedQty(inventory.getReservedQty() + qty);
198	            inventoryService.saveInventory(inventory);
199	        }
200	
201	        String reservationRef = documentRefGenerator.next(InventoryDocumentType.RESERVATION);
202	        for (Map.Entry<UUID, Integer> entry : quantitiesByListing.entrySet()) {
203	            InventoryRecord inventory = inventoryByListing.get(entry.getKey());
204	            int qty = entry.getValue();
205	            inventoryService.createSystemMovement(
206	                inventory,
207	                InventoryDocumentType.RESERVATION,
208	                reservationRef,
209	                -qty,
210	                memberId,
211	                warehouse.getId(),
212	                "Stock reserved for order checkout"
213	            );
214	        }
215	
216	        Order order = new Order();
217	        order.setId(UUID.randomUUID());
218	        order.setMember(member);
219	        order.setStatus(OrderStatus.RESERVED);
220	        order.setTotalAmount(totalAmount.setScale(2, RoundingMode.HALF_UP));
221	        order.setDiscountAmount(discountAmount.setScale(2, RoundingMode.HALF_UP));
222	        order.setFinalAmount(finalAmount);
223	        order.setFulfillmentWarehouse(warehouse);
224	        order.setReservationExpiresAt(LocalDateTime.now().plusMinutes(30));
225	        order.setIdempotencyKey(idempotencyKey);
226	        order.setCreatedAt(LocalDateTime.now());
227	        order.setUpdatedAt(LocalDateTime.now());
228	        orderRepository.save(order);
229	
230	        List<OrderItem> items = new ArrayList<>();
231	        for (OrderItemDraft draft : drafts) {
232	            OrderItem item = new OrderItem();
233	            item.setId(UUID.randomUUID());
234	            item.setOrder(order);
235	            item.setListing(draft.listing());
236	            item.setQuantity(draft.quantity());
237	            item.setUnitPrice(draft.listing().getPrice());
238	            item.setAppliedBenefit(draft.appliedBenefit());
239	            items.add(item);
240	        }
241	        orderItemRepository.saveAll(items);
242	
243	        auditLogService.log(
244	            "ORDER",
245	            order.getId(),
246	            "CREATE_RESERVED",
247	            memberId,
248	            Map.of(
249	                "status", order.getStatus().name(),
250	                "totalAmount", order.getTotalAmount(),
251	                "discountAmount", order.getDiscountAmount(),
252	                "finalAmount", order.getFinalAmount(),
253	                "warehouseId", warehouse.getId()
254	            ),
255	            ipAddress
256	        );
257	
258	        return toOrderResponse(order, items, appliedBenefitTotals);
259	    }
