261	    @Transactional
262	    public OrderResponse confirmOrder(UUID orderId, UUID memberId, String idempotencyKey, String ipAddress) {
263	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
264	            throw new ApiException(HttpStatus.BAD_REQUEST, "IDEMPOTENCY_KEY_REQUIRED", "X-Idempotency-Key header is required");
265	        }
266	
267	        Optional<InternalTenderRecord> existingTender = internalTenderRecordRepository.findByIdempotencyKey(idempotencyKey);
268	        if (existingTender.isPresent()) {
269	            return toOrderResponse(existingTender.get().getOrder());
270	        }
271	
272	        Order order = orderRepository.lockById(orderId)
273	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "ORDER_NOT_FOUND", "Order was not found"));
274	        if (!order.getMember().getId().equals(memberId)) {
275	            throw new ApiException(HttpStatus.FORBIDDEN, "FORBIDDEN", "You can only confirm your own order");
276	        }
277	        if (order.getStatus() != OrderStatus.RESERVED) {
278	            throw new ApiException(HttpStatus.CONFLICT, "INVALID_ORDER_STATE", "Only RESERVED orders can be confirmed");
279	        }
280	        if (order.getReservationExpiresAt() != null && order.getReservationExpiresAt().isBefore(LocalDateTime.now())) {
281	            throw new ApiException(HttpStatus.CONFLICT, "RESERVATION_EXPIRED", "Order reservation has expired");
282	        }
283	
284	        List<OrderItem> items = orderItemRepository.findByOrder_Id(order.getId());
285	        List<UUID> listingIds = items.stream().map(oi -> oi.getListing().getId()).toList();
286	
287	        List<InventoryRecord> lockedInventories = inventoryService.lockInventoriesByWarehouseAndListings(
288	            order.getFulfillmentWarehouse().getId(),
289	            listingIds
290	        );
291	        Map<UUID, InventoryRecord> inventoryByListing = lockedInventories.stream()
292	            .collect(Collectors.toMap(ir -> ir.getListing().getId(), Function.identity()));
293	
294	        String deductionRef = documentRefGenerator.next(InventoryDocumentType.ORDER_DEDUCTION);
295	        for (OrderItem item : items) {
296	            InventoryRecord inventory = inventoryByListing.get(item.getListing().getId());
297	            if (inventory == null || inventory.getReservedQty() < item.getQuantity()) {
298	                throw new ApiException(HttpStatus.CONFLICT, "STOCK_UNAVAILABLE", "Reserved stock no longer available for confirmation");
299	            }
300	
301	            inventory.setReservedQty(inventory.getReservedQty() - item.getQuantity());
302	            inventoryService.saveInventory(inventory);
303	
304	            inventoryService.createSystemMovement(
305	                inventory,
306	                InventoryDocumentType.ORDER_DEDUCTION,
307	                deductionRef,
308	                -item.getQuantity(),
309	                memberId,
310	                order.getFulfillmentWarehouse().getId(),
311	                "Order confirmed and stock deducted"
312	            );
313	        }
314	
315	        InternalTenderRecord tender = new InternalTenderRecord();
316	        tender.setId(UUID.randomUUID());
317	        tender.setOrder(order);
318	        tender.setType(TenderType.PAYMENT);
319	        tender.setAmount(order.getFinalAmount());
320	        tender.setStatus(TenderStatus.COMPLETED);
321	        tender.setIdempotencyKey(idempotencyKey);
322	        tender.setReconciliationRef("PAY-" + order.getId().toString().substring(0, 8));
323	        tender.setCreatedAt(LocalDateTime.now());
324	        internalTenderRecordRepository.save(tender);
325	
326	        order.setStatus(OrderStatus.CONFIRMED);
327	        order.setUpdatedAt(LocalDateTime.now());
328	        orderRepository.save(order);
329	
330	        Membership membership = membershipRepository.findByUser_Id(memberId)
331	            .orElseThrow(() -> new ApiException(HttpStatus.BAD_REQUEST, "MEMBERSHIP_NOT_FOUND", "Membership record not found"));
332	        BigDecimal newTotalSpend = membership.getTotalSpend().add(order.getFinalAmount());
333	        membership.setTotalSpend(newTotalSpend);
334	
335	        TierConfig tierForSpend = tierConfigRepository.findBestTierForSpend(newTotalSpend).orElse(membership.getTier());
336	        if (tierForSpend.getRank() > membership.getTier().getRank()) {
337	            membership.setTier(tierForSpend);
338	            membership.setUpgradedAt(LocalDateTime.now());
339	            membership.setTierValidUntil(LocalDate.now().plusYears(1));
340	        }
341	        membershipRepository.save(membership);
342	
343	        Map<UUID, BigDecimal> benefitTotals = new LinkedHashMap<>();
344	        for (OrderItem item : items) {
345	            if (item.getAppliedBenefit() == null) {
346	                continue;
347	            }
348	
349	            BigDecimal appliedValue = calculateAppliedValue(item);
350	            benefitTotals.merge(item.getAppliedBenefit().getId(), appliedValue, BigDecimal::add);
351	
352	            BenefitIssuance issuance = new BenefitIssuance();
353	            issuance.setId(UUID.randomUUID());
354	            issuance.setMembership(membership);
355	            issuance.setBenefit(item.getAppliedBenefit());
356	            issuance.setOrder(order);
357	            issuance.setAppliedValue(appliedValue);
358	            issuance.setIssuedAt(LocalDateTime.now());
359	            benefitIssuanceRepository.save(issuance);
360	        }
361	
362	        for (OrderItem item : items) {
363	            Listing listing = item.getListing();
364	            listing.setOrderCount7d(listing.getOrderCount7d() + item.getQuantity());
365	            listingRepository.save(listing);
366	        }
367	
368	        auditLogService.log(
369	            "ORDER",
370	            order.getId(),
371	            "CONFIRM",
372	            memberId,
373	            Map.of("status", order.getStatus().name(), "idempotencyKey", idempotencyKey),
374	            ipAddress
375	        );
376	
377	        return toOrderResponse(order, items, benefitTotals);
378	    }
