380	    @Transactional
381	    public OrderResponse cancelOrder(UUID orderId, JwtUserPrincipal principal, String ipAddress) {
382	        Order order = orderRepository.lockById(orderId)
383	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "ORDER_NOT_FOUND", "Order was not found"));
384	
385	        boolean isOwner = order.getMember().getId().equals(principal.userId());
386	        if (!(isOwner || principal.role() == UserRole.ADMIN)) {
387	            throw new ApiException(HttpStatus.FORBIDDEN, "FORBIDDEN", "You cannot cancel this order");
388	        }
389	
390	        if (order.getStatus() == OrderStatus.CANCELLED) {
391	            return toOrderResponse(order);
392	        }
393	
394	        List<OrderItem> items = orderItemRepository.findByOrder_Id(order.getId());
395	        List<UUID> listingIds = items.stream().map(oi -> oi.getListing().getId()).toList();
396	        List<InventoryRecord> lockedInventories = inventoryService.lockInventoriesByWarehouseAndListings(
397	            order.getFulfillmentWarehouse().getId(),
398	            listingIds
399	        );
400	        Map<UUID, InventoryRecord> inventoryByListing = lockedInventories.stream()
401	            .collect(Collectors.toMap(ir -> ir.getListing().getId(), Function.identity()));
402	
403	        if (order.getStatus() == OrderStatus.RESERVED) {
404	            String releaseRef = documentRefGenerator.next(InventoryDocumentType.RESERVATION_RELEASE);
405	            String rollbackRef = documentRefGenerator.next(InventoryDocumentType.CANCELLATION_ROLLBACK);
406	
407	            for (OrderItem item : items) {
408	                InventoryRecord inventory = inventoryByListing.get(item.getListing().getId());
409	                inventory.setAvailableQty(inventory.getAvailableQty() + item.getQuantity());
410	                inventory.setReservedQty(Math.max(0, inventory.getReservedQty() - item.getQuantity()));
411	                inventoryService.saveInventory(inventory);
412	
413	                inventoryService.createSystemMovement(
414	                    inventory,
415	                    InventoryDocumentType.RESERVATION_RELEASE,
416	                    releaseRef,
417	                    item.getQuantity(),
418	                    principal.userId(),
419	                    order.getFulfillmentWarehouse().getId(),
420	                    "Reservation released due to cancellation"
421	                );
422	
423	                inventoryService.createSystemMovement(
424	                    inventory,
425	                    InventoryDocumentType.CANCELLATION_ROLLBACK,
426	                    rollbackRef,
427	                    item.getQuantity(),
428	                    principal.userId(),
429	                    order.getFulfillmentWarehouse().getId(),
430	                    "Cancellation rollback"
431	                );
432	            }
433	        } else if (order.getStatus() == OrderStatus.CONFIRMED) {
434	            String rollbackRef = documentRefGenerator.next(InventoryDocumentType.CANCELLATION_ROLLBACK);
435	            for (OrderItem item : items) {
436	                InventoryRecord inventory = inventoryByListing.get(item.getListing().getId());
437	                inventory.setAvailableQty(inventory.getAvailableQty() + item.getQuantity());
438	                inventoryService.saveInventory(inventory);
439	
440	                inventoryService.createSystemMovement(
441	                    inventory,
442	                    InventoryDocumentType.CANCELLATION_ROLLBACK,
443	                    rollbackRef,
444	                    item.getQuantity(),
445	                    principal.userId(),
446	                    order.getFulfillmentWarehouse().getId(),
447	                    "Confirmed order rollback"
448	                );
449	            }
450	
451	            InternalTenderRecord refund = new InternalTenderRecord();
452	            refund.setId(UUID.randomUUID());
453	            refund.setOrder(order);
454	            refund.setType(TenderType.REFUND);
455	            refund.setAmount(order.getFinalAmount());
456	            refund.setStatus(TenderStatus.COMPLETED);
457	            refund.setIdempotencyKey("refund-" + order.getId() + "-" + System.currentTimeMillis());
458	            refund.setReconciliationRef("REF-" + order.getId().toString().substring(0, 8));
459	            refund.setCreatedAt(LocalDateTime.now());
460	            internalTenderRecordRepository.save(refund);
461	        }
462	
463	        order.setStatus(OrderStatus.CANCELLED);
464	        order.setUpdatedAt(LocalDateTime.now());
465	        orderRepository.save(order);
466	
467	        auditLogService.log(
468	            "ORDER",
469	            order.getId(),
470	            "CANCEL",
471	            principal.userId(),
472	            Map.of("status", order.getStatus().name()),
473	            ipAddress
474	        );
475	
476	        return toOrderResponse(order, items, Map.of());
477	    }
