479	    @Transactional
480	    public OrderResponse fulfillOrder(UUID orderId, UUID actorId, String ipAddress) {
481	        Order order = orderRepository.lockById(orderId)
482	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "ORDER_NOT_FOUND", "Order was not found"));
483	
484	        if (order.getStatus() != OrderStatus.CONFIRMED) {
485	            throw new ApiException(HttpStatus.CONFLICT, "INVALID_ORDER_STATE", "Only CONFIRMED orders can be fulfilled");
486	        }
487	
488	        order.setStatus(OrderStatus.FULFILLED);
489	        order.setUpdatedAt(LocalDateTime.now());
490	        orderRepository.save(order);
491	
492	        auditLogService.log(
493	            "ORDER",
494	            order.getId(),
495	            "FULFILL",
496	            actorId,
497	            Map.of("status", order.getStatus().name()),
498	            ipAddress
499	        );
500	
501	        return toOrderResponse(order);
502	    }
