504	    @Transactional(readOnly = true)
505	    public Page<OrderResponse> myOrders(UUID memberId, OrderStatus status, Pageable pageable) {
506	        Page<Order> page = status == null
507	            ? orderRepository.findByMember_IdOrderByCreatedAtDesc(memberId, pageable)
508	            : orderRepository.findByMember_IdAndStatusOrderByCreatedAtDesc(memberId, status, pageable);
509	
510	        return page.map(this::toOrderResponse);
511	    }
