513	    @Transactional(readOnly = true)
514	    public OrderResponse getOrder(UUID orderId, JwtUserPrincipal principal) {
515	        Order order = orderRepository.findById(orderId)
516	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "ORDER_NOT_FOUND", "Order was not found"));
517	
518	        if (principal.role() != UserRole.ADMIN && !order.getMember().getId().equals(principal.userId())) {
519	            throw new ApiException(HttpStatus.FORBIDDEN, "FORBIDDEN", "You cannot access this order");
520	        }
521	
522	        return toOrderResponse(order);
523	    }
