525	    private Map<UUID, Integer> collapseQuantities(List<CreateOrderItemRequest> items) {
526	        Map<UUID, Integer> quantities = new LinkedHashMap<>();
527	        for (CreateOrderItemRequest item : items) {
528	            quantities.merge(item.listingId(), item.quantity(), Integer::sum);
529	        }
530	        return quantities;
531	    }
