533	    private Map<UUID, Listing> loadListings(Set<UUID> listingIds) {
534	        Map<UUID, Listing> listings = new HashMap<>();
535	        for (UUID listingId : listingIds) {
536	            Listing listing = listingRepository.findByIdAndStatusNot(listingId, ListingStatus.REMOVED)
537	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "LISTING_NOT_FOUND", "Listing was not found: " + listingId));
538	            listings.put(listingId, listing);
539	        }
540	        return listings;
541	    }
