543	    private Warehouse chooseFulfillmentWarehouse(Map<UUID, Integer> quantitiesByListing, CreateOrderRequest request) {
544	        List<InventoryRecord> all = inventoryService.findInventoriesByListingIds(new ArrayList<>(quantitiesByListing.keySet()));
545	        Map<UUID, List<InventoryRecord>> byWarehouse = all.stream()
546	            .collect(Collectors.groupingBy(ir -> ir.getWarehouse().getId()));
547	
548	        List<WarehouseCandidate> candidates = new ArrayList<>();
549	        for (List<InventoryRecord> warehouseRecords : byWarehouse.values()) {
550	            Map<UUID, InventoryRecord> byListing = warehouseRecords.stream()
551	                .collect(Collectors.toMap(ir -> ir.getListing().getId(), Function.identity(), (a, b) -> a));
552	
553	            boolean canFulfill = true;
554	            int stockScore = 0;
555	            for (Map.Entry<UUID, Integer> entry : quantitiesByListing.entrySet()) {
556	                InventoryRecord record = byListing.get(entry.getKey());
557	                if (record == null || record.getAvailableQty() < entry.getValue()) {
558	                    canFulfill = false;
559	                    break;
560	                }
561	                stockScore += record.getAvailableQty();
562	            }
563	
564	            if (canFulfill) {
565	                Warehouse warehouse = warehouseRecords.get(0).getWarehouse();
566	                double distance = calculateDistance(request, warehouse);
567	                candidates.add(new WarehouseCandidate(warehouse, distance, stockScore));
568	            }
569	        }
570	
571	        if (candidates.isEmpty()) {
572	            throw new ApiException(HttpStatus.CONFLICT, "STOCK_UNAVAILABLE", "No single warehouse can fulfill all requested items");
573	        }
574	
575	        candidates.sort(
576	            Comparator.comparingDouble(WarehouseCandidate::distanceMiles)
577	                .thenComparing(Comparator.comparingInt(WarehouseCandidate::stockScore).reversed())
578	        );
579	        return candidates.get(0).warehouse();
580	    }
