582	    private double calculateDistance(CreateOrderRequest request, Warehouse warehouse) {
583	        if (request.deliveryLat() == null || request.deliveryLng() == null) {
584	            return Double.MAX_VALUE;
585	        }
586	        if (warehouse.getLatitude() == null || warehouse.getLongitude() == null) {
587	            return Double.MAX_VALUE;
588	        }
589	        return geoDistanceUtil.haversineMiles(
590	            request.deliveryLat().doubleValue(),
591	            request.deliveryLng().doubleValue(),
592	            warehouse.getLatitude().doubleValue(),
593	            warehouse.getLongitude().doubleValue()
594	        );
595	    }
