597	    private boolean isBenefitApplicable(BenefitPackage benefit, Listing listing) {
598	        LocalDate today = LocalDate.now();
599	        boolean categoryOk = benefit.getScopeCategory() == null || benefit.getScopeCategory().equalsIgnoreCase(listing.getCategory());
600	        boolean sellerOk = benefit.getScopeSeller() == null || benefit.getScopeSeller().getId().equals(listing.getSeller().getId());
601	        boolean startOk = benefit.getScopeDateStart() == null || !today.isBefore(benefit.getScopeDateStart());
602	        boolean endOk = benefit.getScopeDateEnd() == null || !today.isAfter(benefit.getScopeDateEnd());
603	        return categoryOk && sellerOk && startOk && endOk;
604	    }
605	
606	    private BigDecimal calculateAppliedValue(OrderItem item) {
607	        BenefitPackage benefit = item.getAppliedBenefit();
608	        if (benefit == null) {
609	            return BigDecimal.ZERO;
610	        }
611	        BigDecimal base = item.getUnitPrice().multiply(BigDecimal.valueOf(item.getQuantity()));
612	
613	        if (benefit.getType() == BenefitType.EXCLUSIVE_PRICE) {
614	            BigDecimal exclusive = benefit.getValue().multiply(BigDecimal.valueOf(item.getQuantity()));
615	            return base.subtract(exclusive).max(BigDecimal.ZERO).setScale(2, RoundingMode.HALF_UP);
616	        }
617	        if (benefit.getType() == BenefitType.PERCENTAGE_DISCOUNT) {
618	            return base.multiply(benefit.getValue()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_UP);
619	        }
620	        return BigDecimal.ZERO;
621	    }
