623	    private OrderResponse toOrderResponse(Order order) {
624	        List<OrderItem> items = orderItemRepository.findByOrder_Id(order.getId());
625	        Map<UUID, BigDecimal> benefitTotals = new LinkedHashMap<>();
626	        for (OrderItem item : items) {
627	            if (item.getAppliedBenefit() != null) {
628	                benefitTotals.merge(item.getAppliedBenefit().getId(), calculateAppliedValue(item), BigDecimal::add);
629	            }
630	        }
631	        return toOrderResponse(order, items, benefitTotals);
632	    }
