635	        Map<UUID, BenefitPackage> benefitById = items.stream()
636	            .map(OrderItem::getAppliedBenefit)
637	            .filter(b -> b != null)
638	            .collect(Collectors.toMap(BenefitPackage::getId, Function.identity(), (a, b) -> a));
639	
640	        List<OrderItemResponse> itemResponses = items.stream()
641	            .map(item -> new OrderItemResponse(
642	                item.getListing().getId(),
643	                item.getListing().getTitle(),
644	                item.getQuantity(),
