646	                item.getUnitPrice().multiply(BigDecimal.valueOf(item.getQuantity())),
647	                item.getAppliedBenefit() == null ? null : item.getAppliedBenefit().getId()
648	            ))
649	            .toList();
650	
651	        List<OrderBenefitResponse> benefitResponses = benefitTotals.entrySet().stream()
652	            .map(entry -> {
653	                BenefitPackage benefit = benefitById.get(entry.getKey());
654	                if (benefit == null) {
655	                    return null;
656	                }
657	                return new OrderBenefitResponse(benefit.getId(), benefit.getName(), benefit.getType(), entry.getValue());
658	            })
659	            .filter(response -> response != null)
660	            .toList();
661	
662	        return new OrderResponse(
663	            order.getId(),
664	            order.getStatus(),
665	            order.getTotalAmount(),
666	            order.getDiscountAmount(),
667	            order.getFinalAmount(),
668	            order.getFulfillmentWarehouse() == null ? null : order.getFulfillmentWarehouse().getId(),
669	            order.getReservationExpiresAt(),
670	            order.getIdempotencyKey(),
671	            order.getCreatedAt(),
672	            order.getUpdatedAt(),
673	            itemResponses,
674	            benefitResponses
675	        );
676	    }
