103	                predicates.add(cb.equal(root.get("severity"), severity));
104	            }
105	            if (type != null) {
106	                predicates.add(cb.equal(root.get("type"), type));
107	            }
108	            if (assignedTo != null) {
109	                predicates.add(cb.equal(root.get("assignedTo").get("id"), assignedTo));
110	            }
111	
112	            query.orderBy(cb.desc(root.get("createdAt")));
113	            return cb.and(predicates.toArray(Predicate[]::new));
