317	    private void validateTransition(TicketStatus current, TicketStatus target) {
318	        if (current == target) {
319	            return;
320	        }
321	
322	        Map<TicketStatus, Set<TicketStatus>> transitions = new EnumMap<>(TicketStatus.class);
323	        transitions.put(TicketStatus.OPEN, Set.of(TicketStatus.ACKNOWLEDGED, TicketStatus.IN_PROGRESS, TicketStatus.ESCALATED));
324	        transitions.put(TicketStatus.ACKNOWLEDGED, Set.of(TicketStatus.IN_PROGRESS, TicketStatus.RESOLVED, TicketStatus.ESCALATED));
325	        transitions.put(TicketStatus.IN_PROGRESS, Set.of(TicketStatus.RESOLVED, TicketStatus.ESCALATED));
326	        transitions.put(TicketStatus.ESCALATED, Set.of(TicketStatus.ACKNOWLEDGED, TicketStatus.IN_PROGRESS, TicketStatus.RESOLVED));
327	        transitions.put(TicketStatus.RESOLVED, Set.of(TicketStatus.CLOSED));
328	        transitions.put(TicketStatus.CLOSED, Set.of());
329	
330	        Set<TicketStatus> allowed = transitions.getOrDefault(current, Set.of());
331	        if (!allowed.contains(target)) {
332	            throw new ApiException(
333	                HttpStatus.BAD_REQUEST,
334	                "INVALID_TRANSITION",
335	                "Invalid ticket status transition from %s to %s".formatted(current.name(), target.name())
336	            );
337	        }
338	    }
