341	        return new TicketResponse(
342	            ticket.getId(),
343	            ticket.getReporter().getId(),
344	            ticket.getReporter().getDisplayName(),
345	            ticket.getType(),
346	            ticket.getSeverity(),
347	            ticket.getStatus(),
348	            ticket.getAssignedTo() == null ? null : ticket.getAssignedTo().getId(),
349	            ticket.getAssignedTo() == null ? null : ticket.getAssignedTo().getDisplayName(),
350	            ticket.getLocationAddress(),
351	            ticket.getLocationCrossStreet(),
352	            ticket.getDescription(),
353	            ticket.getClosureCode(),
354	            ticket.getClosureNotes(),
355	            ticket.getSlaAcknowledgeBy() == null ? ticket.getCreatedAt().plusMinutes(15) : ticket.getSlaAcknowledgeBy(),
356	            ticket.getSlaResolveBy() == null ? ticket.getCreatedAt().plusHours(24) : ticket.getSlaResolveBy(),
357	            ticket.getAcknowledgedAt(),
358	            ticket.getResolvedAt(),
359	            ticket.getEscalatedAt(),
360	            ticket.getCreatedAt()
361	        );
362	    }
