120	    public List<InventoryDocumentMovementResponse> processDocument(InventoryDocumentRequest request, JwtUserPrincipal principal) {
121	        if (request.type() != InventoryDocumentType.INBOUND && request.type() != InventoryDocumentType.OUTBOUND) {
122	            throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_DOCUMENT_TYPE", "Only INBOUND and OUTBOUND are allowed for this endpoint");
123	        }
124	
125	        warehouseRepository.findById(request.warehouseId())
126	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "WAREHOUSE_NOT_FOUND", "Warehouse was not found"));
127	
128	        String documentRef = documentRefGenerator.next(request.type());
129	        List<InventoryDocumentMovementResponse> responses = new ArrayList<>();
130	
131	        for (InventoryDocumentItemRequest item : request.items()) {
132	            InventoryRecord inventory = resolveInventoryForDocument(item, request.warehouseId(), request.type());
133	            ensureCanManageSellerInventory(principal, inventory);
134	
135	            int delta = request.type() == InventoryDocumentType.INBOUND ? item.quantity() : -item.quantity();
136	            int nextAvailable = inventory.getAvailableQty() + delta;
137	            if (nextAvailable < 0) {
138	                throw new ApiException(HttpStatus.CONFLICT, "INSUFFICIENT_STOCK", "Outbound quantity exceeds available stock");
139	            }
140	
141	            inventory.setAvailableQty(nextAvailable);
142	            inventoryRecordRepository.save(inventory);
143	
144	            InventoryMovement movement = inventoryMovementService.record(
145	                inventory,
146	                request.type(),
147	                documentRef,
148	                delta,
149	                principal.userId(),
150	                request.warehouseId(),
151	                item.notes()
152	            );
153	
154	            responses.add(new InventoryDocumentMovementResponse(
155	                movement.getId(),
156	                inventory.getId(),
157	                inventory.getListing().getId(),
158	                inventory.getWarehouse().getId(),
159	                request.type(),
160	                documentRef,
161	                delta,
162	                inventory.getAvailableQty(),
163	                inventory.getAvailableQty() < inventory.getLowStockThreshold()
164	            ));
165	        }
166	
167	        return responses;
168	    }
