238	    private InventoryRecord resolveInventoryForDocument(
239	        InventoryDocumentItemRequest item,
240	        UUID warehouseId,
241	        InventoryDocumentType type
242	    ) {
243	        if (item.inventoryId() != null) {
244	            return inventoryRecordRepository.lockById(item.inventoryId())
245	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "INVENTORY_NOT_FOUND", "Inventory record not found"));
246	        }
247	
248	        if (item.listingId() == null) {
249	            throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ITEM", "Each item must include inventory_id or listing_id");
250	        }
251	
252	        List<InventoryRecord> existing = inventoryRecordRepository.findByListing_IdAndWarehouse_Id(item.listingId(), warehouseId);
253	        if (!existing.isEmpty()) {
254	            return existing.get(0);
255	        }
