174	    @Transactional
175	    public int generateRepeatIncidentFlags() {
176	        LocalDate windowEnd = LocalDate.now();
177	        LocalDate windowStart = windowEnd.minusDays(29);
178	        LocalDateTime startAt = windowStart.atStartOfDay();
179	
180	        List<Ticket> recentTickets = ticketRepository.findByCreatedAtAfter(startAt);
181	        if (recentTickets.isEmpty()) {
182	            return 0;
183	        }
184	
185	        Map<UUID, Integer> incidentsByUser = new HashMap<>();
186	        for (Ticket ticket : recentTickets) {
187	            incidentsByUser.merge(ticket.getReporter().getId(), 1, Integer::sum);
188	        }
189	
190	        int updated = 0;
191	        for (Map.Entry<UUID, Integer> entry : incidentsByUser.entrySet()) {
192	            if (entry.getValue() <= 3) {
193	                continue;
194	            }
195	
196	            User user = userRepository.findById(entry.getKey()).orElse(null);
197	            if (user == null) {
198	                continue;
199	            }
200	
201	            RiskEntityType entityType = mapRoleToEntityType(user.getRole());
202	            if (entityType == null) {
203	                continue;
204	            }
205	
206	            RiskFlag flag = riskFlagRepository.findByEntityTypeAndEntityIdAndFlagTypeAndWindowStartAndWindowEnd(
207	                    entityType,
208	                    user.getId(),
209	                    RiskFlagType.REPEAT_INCIDENTS,
210	                    windowStart,
211	                    windowEnd
212	                )
213	                .orElseGet(() -> {
214	                    RiskFlag created = new RiskFlag();
215	                    created.setId(UUID.randomUUID());
216	                    created.setEntityType(entityType);
217	                    created.setEntityId(user.getId());
218	                    created.setFlagType(RiskFlagType.REPEAT_INCIDENTS);
219	                    created.setWindowStart(windowStart);
220	                    created.setWindowEnd(windowEnd);
221	                    created.setCreatedAt(LocalDateTime.now());
222	                    return created;
223	                });
224	
225	            flag.setIncidentCount(entry.getValue());
226	            riskFlagRepository.save(flag);
227	            updated++;
228	
229	            auditLogService.log(
230	                "RISK_FLAG",
231	                flag.getId(),
232	                "UPSERT_REPEAT_INCIDENTS",
233	                user.getId(),
234	                Map.of("incidentCount", flag.getIncidentCount(), "entityType", entityType.name()),
235	                "system"
236	            );
237	        }
238	        return updated;
239	    }
