241	    private List<TopFlaggedEntityResponse> buildTopFlagged(RiskEntityType type) {
242	        List<RiskFlag> topFlags = riskFlagRepository.findTop10ByEntityTypeOrderByIncidentCountDescCreatedAtDesc(type);
243	        if (topFlags.isEmpty()) {
244	            return List.of();
245	        }
246	
247	        Map<UUID, User> users = userRepository.findAllById(topFlags.stream().map(RiskFlag::getEntityId).toList())
248	            .stream()
249	            .collect(java.util.stream.Collectors.toMap(User::getId, u -> u));
250	
251	        List<TopFlaggedEntityResponse> response = new ArrayList<>();
252	        for (RiskFlag flag : topFlags) {
253	            User user = users.get(flag.getEntityId());
254	            response.add(new TopFlaggedEntityResponse(
255	                flag.getEntityId(),
256	                user == null ? "Unknown" : user.getDisplayName(),
257	                flag.getFlagType(),
258	                flag.getIncidentCount(),
259	                flag.getWindowStart(),
260	                flag.getWindowEnd()
261	            ));
262	        }
263	
264	        return response;
265	    }
