270	            flag.getEntityType(),
271	            flag.getEntityId(),
272	            flag.getFlagType(),
273	            flag.getIncidentCount(),
274	            flag.getWindowStart(),
275	            flag.getWindowEnd(),
276	            flag.getCreatedAt()
277	        );
278	    }
279	
280	    private double computeRiskScore(List<RiskFlag> flags) {
281	        if (flags.isEmpty()) {
282	            return 0;
283	        }
284	
285	        double score = 0;
286	        LocalDate today = LocalDate.now();
287	        for (RiskFlag flag : flags) {
288	            double typeWeight = switch (flag.getFlagType()) {
289	                case REPEAT_INCIDENTS -> 2.0;
290	                case MISSED_CHECKINS -> 1.2;
291	                case BUDDY_PUNCHING -> 1.8;
292	                case MISIDENTIFICATION -> 1.6;
293	            };
294	
295	            long daysSinceEnd = Math.max(0, ChronoUnit.DAYS.between(flag.getWindowEnd(), today));
296	            double recencyMultiplier = 1.0 / (1.0 + (daysSinceEnd / 30.0));
297	            score += flag.getIncidentCount() * typeWeight * recencyMultiplier;
298	        }
299	
300	        return round2(Math.min(100.0, score));
301	    }
302	
303	    private String buildRecommendation(RiskEntityType entityType, double riskScore) {
304	        if (riskScore >= 75) {
305	            return switch (entityType) {
306	                case SELLER -> "Review seller activity. Consider temporary suspension.";
307	                case MEMBER -> "Escalate member behavior review and restrict high-risk transactions.";
308	                case STAFF -> "Launch immediate supervisor review and temporary access restrictions.";
309	            };
310	        }
311	
312	        if (riskScore >= 45) {
313	            return switch (entityType) {
314	                case SELLER -> "Monitor seller listings closely and require compliance checks.";
315	                case MEMBER -> "Monitor member incidents and apply enhanced verification.";
316	                case STAFF -> "Increase staff supervision and validate operational check-ins.";
317	            };
318	        }
319	
320	        return "Continue routine monitoring. No immediate intervention required.";
321	    }
322	
323	    private RiskEntityType mapRoleToEntityType(UserRole role) {
324	        return switch (role) {
325	            case SELLER -> RiskEntityType.SELLER;
326	            case MEMBER -> RiskEntityType.MEMBER;
327	            case WAREHOUSE_STAFF, MODERATOR, ADMIN -> RiskEntityType.STAFF;
328	            default -> null;
329	        };
330	    }
331	
332	    private double round2(double value) {
333	        return Math.round(value * 100.0) / 100.0;
334	    }
335	}
