74	    @Transactional
75	    public AppealDetailResponse createAppeal(
76	        UUID ticketId,
77	        String reason,
78	        List<MultipartFile> evidenceFiles,
79	        JwtUserPrincipal principal,
80	        String ipAddress
81	    ) {
82	        String sanitizedReason = inputSanitizer.sanitize(reason);
83	        if (sanitizedReason == null || sanitizedReason.length() < 10 || sanitizedReason.length() > 5000) {
84	            throw new ApiException(HttpStatus.BAD_REQUEST, "VALIDATION_ERROR", "reason must be between 10 and 5000 characters");
85	        }
86	
87	        Ticket ticket = ticketRepository.findById(ticketId)
88	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "TICKET_NOT_FOUND", "Ticket was not found"));
89	
90	        if (!ticket.getReporter().getId().equals(principal.userId())) {
91	            throw new ApiException(HttpStatus.FORBIDDEN, "FORBIDDEN", "You can only submit appeals for your own tickets");
92	        }
93	
94	        List<MultipartFile> files = evidenceFiles == null ? List.of() : evidenceFiles.stream()
95	            .filter(file -> file != null && !file.isEmpty())
96	            .toList();
97	
98	        List<Map<String, Object>> validationErrors = fileUploadSecurityValidator.validateEvidenceFiles(files);
99	        if (!validationErrors.isEmpty()) {
100	            throw new ApiException(
101	                HttpStatus.BAD_REQUEST,
102	                "EVIDENCE_VALIDATION_FAILED",
103	                "Evidence validation failed",
104	                Map.of("files", validationErrors)
105	            );
106	        }
107	
108	        User appellant = userRepository.findById(principal.userId())
109	            .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "USER_NOT_FOUND", "Appellant was not found"));
110	
111	        Appeal appeal = new Appeal();
112	        appeal.setId(UUID.randomUUID());
113	        appeal.setTicket(ticket);
114	        appeal.setAppellant(appellant);
115	        appeal.setReason(sanitizedReason);
116	        appeal.setStatus(AppealStatus.SUBMITTED);
117	        appeal.setCreatedAt(LocalDateTime.now());
118	        appeal = appealRepository.save(appeal);
119	
120	        List<AppealEvidence> evidenceRecords = storeEvidenceFiles(appeal, files);
121	        if (!evidenceRecords.isEmpty()) {
122	            appealEvidenceRepository.saveAll(evidenceRecords);
123	        }
124	
125	        auditLogService.log(
126	            "APPEAL",
127	            appeal.getId(),
128	            "CREATE",
129	            principal.userId(),
130	            Map.of("status", appeal.getStatus().name(), "ticketId", ticket.getId(), "evidenceCount", evidenceRecords.size()),
131	            ipAddress
132	        );
133	
134	        return toDetailResponse(appeal, evidenceRecords);
135	    }
