140	            List<Predicate> predicates = new ArrayList<>();
141	
142	            if (!isModeratorOrAdmin(principal)) {
143	                predicates.add(cb.equal(root.get("appellant").get("id"), principal.userId()));
144	            }
145	            if (status != null) {
146	                predicates.add(cb.equal(root.get("status"), status));
147	            }
148	
149	            query.orderBy(cb.desc(root.get("createdAt")));
150	            return cb.and(predicates.toArray(Predicate[]::new));
151	        };
152	        return appealRepository.findAll(spec, pageable).map(this::toResponse);
153	    }
