192	
193	        if (request.decision() == AppealReviewDecision.ESCALATED_TO_ADMIN) {
194	            appeal.setStatus(AppealStatus.ESCALATED_TO_ADMIN);
195	            appeal.setDecidedAt(null);
196	        } else if (request.decision() == AppealReviewDecision.APPROVED) {
