267	    private List<AppealEvidence> storeEvidenceFiles(Appeal appeal, List<MultipartFile> files) {
268	        try {
269	            Path appealDir = uploadRoot.resolve(appeal.getId().toString());
270	            Files.createDirectories(appealDir);
271	
272	            List<AppealEvidence> evidenceList = new ArrayList<>();
273	            for (MultipartFile file : files) {
274	                String original = file.getOriginalFilename() == null ? "file" : file.getOriginalFilename();
275	                String safeOriginal = fileUploadSecurityValidator.sanitizeFileName(original);
276	                String storedName = UUID.randomUUID() + "_" + safeOriginal;
277	                Path target = appealDir.resolve(storedName);
278	                Files.copy(file.getInputStream(), target, StandardCopyOption.REPLACE_EXISTING);
279	
280	                AppealEvidence evidence = new AppealEvidence();
281	                evidence.setId(UUID.randomUUID());
282	                evidence.setAppeal(appeal);
283	                evidence.setFileName(safeOriginal);
284	                evidence.setFilePath(target.toString());
285	                evidence.setMimeType(file.getContentType());
286	                evidence.setFileSizeBytes(file.getSize());
287	                evidence.setUploadedAt(LocalDateTime.now());
288	                evidenceList.add(evidence);
289	            }
290	
291	            return evidenceList;
292	        } catch (IOException ex) {
293	            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "EVIDENCE_STORAGE_FAILED", "Failed to store appeal evidence files");
294	        }
295	    }
