5	@Component
6	public class InputSanitizer {
7	
8	    public String sanitize(String value) {
9	        if (value == null) {
10	            return null;
11	        }
12	
13	        String trimmed = value.trim();
14	        String withoutScripts = trimmed
15	            .replaceAll("(?i)<script.*?>.*?</script>", "")
16	            .replaceAll("(?i)javascript:", "")
17	            .replaceAll("[\\u0000-\\u001F]", "");
18	
19	        return withoutScripts;
20	    }
21	}
