        void returnZeroWhenNoRecentTickets() {
            when(ticketRepository.findByCreatedAtAfter(any())).thenReturn(List.of());

            int result = riskService.generateRepeatIncidentFlags();

            assertEquals(0, result);
        }
    }
}
