48	      .split(",")
49	      .map((tag) => tag.trim())
50	      .filter(Boolean);
51	
52	    return {
53	      keyword: debouncedKeyword || undefined,
54	      neighborhood: filters.neighborhood || undefined,
55	      radius: toNumber(filters.radius),
56	      lat: toNumber(filters.lat),
57	      lng: toNumber(filters.lng),
58	      priceMin: toNumber(filters.priceMin),
59	      priceMax: toNumber(filters.priceMax),
60	      sqftMin: toNumber(filters.sqftMin),
61	      sqftMax: toNumber(filters.sqftMax),
62	      tags: tags.length ? tags : undefined,
63	      availFrom: filters.availFrom || undefined,
64	      availTo: filters.availTo || undefined,
65	      sort: filters.sort,
