166	            </Button>
167	          </div>
168	          {openFilters && (
169	            <div className="filters-grid">
170	              <label>
171	                Neighborhood
172	                <input
173	                  value={filters.neighborhood}
174	                  onChange={(e) =>
175	                    setFilters((prev) => ({
176	                      ...prev,
177	                      neighborhood: e.target.value,
178	                    }))
179	                  }
180	                />
181	              </label>
182	              <label>
183	                Radius (miles)
184	                <input
185	                  value={filters.radius}
186	                  onChange={(e) =>
187	                    setFilters((prev) => ({ ...prev, radius: e.target.value }))
188	                  }
189	                />
190	              </label>
191	              <label>
192	                Latitude
193	                <input
194	                  value={filters.lat}
195	                  onChange={(e) =>
196	                    setFilters((prev) => ({ ...prev, lat: e.target.value }))
197	                  }
198	                />
199	              </label>
200	              <label>
201	                Longitude
202	                <input
203	                  value={filters.lng}
204	                  onChange={(e) =>
205	                    setFilters((prev) => ({ ...prev, lng: e.target.value }))
206	                  }
207	                />
208	              </label>
209	              <label>
210	                Price Min
211	                <input
212	                  value={filters.priceMin}
213	                  onChange={(e) =>
214	                    setFilters((prev) => ({
215	                      ...prev,
216	                      priceMin: e.target.value,
217	                    }))
218	                  }
219	                />
220	              </label>
221	              <label>
222	                Price Max
223	                <input
224	                  value={filters.priceMax}
225	                  onChange={(e) =>
226	                    setFilters((prev) => ({
227	                      ...prev,
228	                      priceMax: e.target.value,
229	                    }))
230	                  }
231	                />
232	              </label>
233	              <label>
234	                Sqft Min
235	                <input
236	                  value={filters.sqftMin}
237	                  onChange={(e) =>
238	                    setFilters((prev) => ({ ...prev, sqftMin: e.target.value }))
239	                  }
240	                />
241	              </label>
242	              <label>
243	                Sqft Max
244	                <input
245	                  value={filters.sqftMax}
246	                  onChange={(e) =>
247	                    setFilters((prev) => ({ ...prev, sqftMax: e.target.value }))
248	                  }
249	                />
250	              </label>
251	              <label>
252	                Tags (comma separated)
253	                <input
254	                  value={filters.tags}
255	                  onChange={(e) =>
256	                    setFilters((prev) => ({ ...prev, tags: e.target.value }))
257	                  }
258	                />
259	              </label>
260	              <label>
261	                Available From
262	                <input
263	                  type="date"
264	                  value={filters.availFrom}
265	                  onChange={(e) =>
266	                    setFilters((prev) => ({
267	                      ...prev,
268	                      availFrom: e.target.value,
269	                    }))
270	                  }
271	                />
272	              </label>
273	              <label>
274	                Available To
275	                <input
276	                  type="date"
277	                  value={filters.availTo}
278	                  onChange={(e) =>
279	                    setFilters((prev) => ({ ...prev, availTo: e.target.value }))
280	                  }
281	                />
282	              </label>
283	              <label>
284	                Sort
285	                <select
286	                  value={filters.sort}
287	                  onChange={(e) =>
288	                    setFilters((prev) => ({ ...prev, sort: e.target.value }))
289	                  }
290	                >
291	                  <option value="newest">Newest</option>
292	                  <option value="price_asc">Price ↑</option>
293	                  <option value="price_desc">Price ↓</option>
294	                  <option value="distance">Distance</option>
295	                  <option value="popularity">Popularity</option>
296	                </select>
297	              </label>
298	            </div>
299	          )}
300	        </div>
301	      </Card>
302	
303	      <section>
304	        <div className="section-heading">
305	          <h2>Results</h2>
306	          <span>{results.length} listings</span>
