332	                </div>
333	                <p className="listing-neighborhood">
334	                  {listing.neighborhood || "Neighborhood n/a"}
335	                </p>
336	                <strong className="listing-price">
337	                  {formatCurrency(listing.price)}
338	                </strong>
339	                <div className="tag-list">
340	                  {(listing.tags || []).slice(0, 4).map((tag) => (
341	                    <span key={tag} className="tag-chip">
342	                      {tag}
343	                    </span>
344	                  ))}
345	                </div>
346	                {filters.sort === "distance" &&
347	                  listing.distance_miles != null && (
348	                    <small>
349	                      {Number(listing.distance_miles).toFixed(2)} miles away
350	                    </small>
351	                  )}
352	              </Link>
353	            ))}
354	          </div>
355	        )}
356	      </section>
357	
358	      <section>
359	        <div className="section-heading">
360	          <h2>Trending This Week</h2>
