1	import { useMemo, useState } from "react";
2	import { orderService } from "../api/orderService";
3	import { useAuth } from "../auth/AuthContext";
4	import { Button } from "../components/Button";
5	import { Card } from "../components/Card";
6	import { CountdownTimer } from "../components/CountdownTimer";
7	import { EmptyState } from "../components/EmptyState";
8	import { useToast } from "../components/ToastProvider";
9	import { useCart } from "../hooks/useCart";
10	import { formatCurrency } from "../utils/formatting";
11	import { generateIdempotencyKey } from "../utils/idempotency";
12	
13	export default function CheckoutPage() {
14	  const { user } = useAuth();
15	  const { showToast } = useToast();
16	  const cart = useCart();
17	  const [address, setAddress] = useState({ lat: "", lng: "" });
18	  const [placing, setPlacing] = useState(false);
19	  const [confirming, setConfirming] = useState(false);
20	  const [order, setOrder] = useState(null);
21	
22	  const subtotal = useMemo(
23	    () =>
24	      cart.items.reduce(
25	        (sum, item) =>
26	          sum + Number(item.price || 0) * Number(item.quantity || 0),
27	        0,
28	      ),
29	    [cart.items],
30	  );
31	
32	  const placeOrder = async () => {
33	    if (cart.items.length === 0) {
34	      return;
35	    }
36	
37	    setPlacing(true);
38	    try {
39	      const payload = {
40	        delivery_lat: address.lat ? Number(address.lat) : undefined,
41	        delivery_lng: address.lng ? Number(address.lng) : undefined,
42	        items: cart.items.map((item) => ({
43	          listing_id: item.id,
44	          quantity: Number(item.quantity),
45	        })),
46	      };
47	      const response = await orderService.create(
48	        payload,
49	        generateIdempotencyKey(),
50	      );
51	      setOrder(response);
52	      showToast(
53	        "Order reserved. Confirm payment within 30 minutes.",
54	        "success",
55	      );
56	    } catch (error) {
57	      showToast(error?.message || "Failed to place order", "error");
58	    } finally {
59	      setPlacing(false);
60	    }
61	  };
62	
63	  const confirmPayment = async () => {
64	    if (!order?.id) {
65	      return;
66	    }
67	
68	    setConfirming(true);
69	    try {
70	      const response = await orderService.confirm(
71	        order.id,
72	        generateIdempotencyKey(),
73	      );
74	      setOrder(response);
75	      cart.clear();
76	      showToast("Payment confirmed successfully", "success");
77	    } catch (error) {
78	      showToast(error?.message || "Failed to confirm payment", "error");
79	    } finally {
80	      setConfirming(false);
81	    }
82	  };
83	
84	  if (user?.role !== "MEMBER") {
85	    return (
86	      <EmptyState
87	        title="Members only"
88	        message="Checkout is available for members."
89	      />
90	    );
91	  }
92	
93	  return (
94	    <div className="checkout-grid">
95	      <Card>
96	        <h2>Cart</h2>
97	        {cart.items.length === 0 ? (
98	          <EmptyState
99	            title="Your cart is empty"
100	            message="Add listings from Browse to start checkout."
101	          />
102	        ) : (
103	          <div className="stack-md">
104	            {cart.items.map((item) => (
105	              <div key={item.id} className="line-item">
106	                <div>
107	                  <strong>{item.title}</strong>
108	                  <small>{formatCurrency(item.price)} each</small>
109	                </div>
110	                <input
111	                  className="qty-input"
112	                  min={1}
113	                  type="number"
114	                  value={item.quantity}
115	                  onChange={(e) =>
116	                    cart.updateQuantity(
117	                      item.id,
118	                      Math.max(1, Number(e.target.value || 1)),
119	                    )
120	                  }
121	                />
122	              </div>
123	            ))}
124	          </div>
125	        )}
126	      </Card>
127	
128	      <Card>
129	        <h2>Tier Card</h2>
130	        <p>
131	          Current Tier: <strong>{user?.tier_name || "Member"}</strong>
132	        </p>
133	        <ul className="plain-list">
134	          <li>Exclusive pricing applies when available.</li>
135	          <li>Percentage discounts stack with free shipping only.</li>
136	          <li>
137	            Higher-priority benefits override lower-priority ones in conflicts.
138	          </li>
139	        </ul>
140	
141	        <h3>Delivery Coordinates</h3>
142	        <div className="filters-grid">
143	          <label>
144	            Latitude
145	            <input
146	              value={address.lat}
147	              onChange={(e) =>
148	                setAddress((prev) => ({ ...prev, lat: e.target.value }))
149	              }
150	            />
151	          </label>
152	          <label>
153	            Longitude
154	            <input
155	              value={address.lng}
156	              onChange={(e) =>
157	                setAddress((prev) => ({ ...prev, lng: e.target.value }))
158	              }
159	            />
160	          </label>
161	        </div>
162	      </Card>
163	
164	      <Card>
165	        <h2>Payment Summary</h2>
166	        <div className="summary-list">
167	          <div>
168	            <span>Subtotal</span>
169	            <strong>{formatCurrency(subtotal)}</strong>
170	          </div>
171	          <div>
172	            <span>Total Discount</span>
173	            <strong>{formatCurrency(order?.discount_amount || 0)}</strong>
174	          </div>
175	          <div>
176	            <span>Final Amount</span>
177	            <strong>{formatCurrency(order?.final_amount || subtotal)}</strong>
178	          </div>
179	        </div>
180	
181	        <h3>Applied Benefits</h3>
182	        {(order?.applied_benefits || []).length > 0 ? (
183	          <ul className="plain-list">
184	            {order.applied_benefits.map((benefit) => (
185	              <li key={benefit.id}>
186	                {benefit.name}: -{formatCurrency(benefit.applied_value)}
187	              </li>
188	            ))}
189	          </ul>
190	        ) : (
191	          <p>No benefits applied yet.</p>
192	        )}
193	
194	        <h3>Blocked Benefits</h3>
195	        <p className="muted">
196	          Your 15% discount may be blocked when an Exclusive Price rule is
197	          active for the same listing.
198	        </p>
199	
200	        <div className="actions-row">
201	          <Button
202	            disabled={placing || cart.items.length === 0}
203	            onClick={placeOrder}
204	          >
205	            {placing ? "Placing..." : "Place Order"}
206	          </Button>
207	          <Button
208	            variant="secondary"
209	            disabled={confirming || !order?.id}
210	            onClick={confirmPayment}
211	          >
212	            {confirming ? "Confirming..." : "Confirm Payment"}
213	          </Button>
214	        </div>
215	
216	        {order?.reservation_expires_at && (
217	          <CountdownTimer
218	            targetDate={order.reservation_expires_at}
219	            label="Reservation timer"
220	          />
221	        )}
222	      </Card>
223	    </div>
224	  );
225	}
