2	import { useNavigate } from "react-router-dom";
3	import { authService } from "../api/authService";
4	import { setRateLimitHandler, setUnauthorizedHandler } from "../api/apiClient";
5	import { useToast } from "../components/ToastProvider";
6	import { getToken, setToken } from "./tokenStore";
7	
8	const AuthContext = createContext(null);
9	
10	export function AuthProvider({ children }) {
11	  const navigate = useNavigate();
12	  const { showToast } = useToast();
13	  const [token, setTokenState] = useState(getToken());
14	  const [user, setUser] = useState(() => {
15	    const raw = localStorage.getItem("hm_user");
16	    return raw ? JSON.parse(raw) : null;
17	  });
18	  const [loading, setLoading] = useState(false);
19	
20	  useEffect(() => {
21	    setUnauthorizedHandler(() => {
22	      setToken("");
23	      setTokenState("");
24	      setUser(null);
25	      localStorage.removeItem("hm_user");
26	      showToast("Session expired. Please login again.", "warn");
27	      navigate("/login");
28	    });
29	
30	    setRateLimitHandler((retryAfter) => {
31	      showToast(`Rate limit exceeded. Try again in ${retryAfter}s`, "warn");
32	    });
33	  }, [navigate, showToast]);
34	
35	  useEffect(() => {
36	    if (!token || user) {
37	      return;
38	    }
39	    let mounted = true;
40	
41	    setLoading(true);
42	    authService
43	      .me()
44	      .then((profile) => {
45	        if (!mounted) return;
46	        setUser(profile);
47	        localStorage.setItem("hm_user", JSON.stringify(profile));
48	      })
49	      .catch(() => {
50	        setToken("");
51	        setTokenState("");
52	      })
53	      .finally(() => {
54	        if (mounted) setLoading(false);
55	      });
56	
57	    return () => {
58	      mounted = false;
59	    };
60	  }, [token, user]);
61	
62	  const login = async (credentials) => {
63	    const result = await authService.login(credentials);
64	    const nextToken = result.access_token;
65	    setToken(nextToken);
66	    setTokenState(nextToken);
67	    const profile = await authService.me();
68	    setUser(profile);
69	    localStorage.setItem("hm_user", JSON.stringify(profile));
70	    showToast("Welcome back.", "success");
71	    return profile;
72	  };
73	
74	  const register = async (payload) => {
75	    return authService.register(payload);
76	  };
77	
78	  const logout = async () => {
79	    try {
80	      if (token) {
81	        await authService.logout();
82	      }
83	    } catch {
84	      // best effort
85	    }
86	    setToken("");
87	    setTokenState("");
88	    setUser(null);
89	    localStorage.removeItem("hm_user");
90	  };
91	
92	  const value = useMemo(
93	    () => ({
94	      token,
95	      user,
96	      loading,
97	      isAuthenticated: Boolean(token),
98	      login,
99	      register,
100	      logout,
101	      refreshProfile: async () => {
102	        const profile = await authService.me();
103	        setUser(profile);
104	        localStorage.setItem("hm_user", JSON.stringify(profile));
105	        return profile;
106	      },
107	    }),
108	    [token, user, loading],
109	  );
110	
111	  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
112	}
113	
114	export function useAuth() {
115	  const context = useContext(AuthContext);
116	  if (!context) {
117	    throw new Error("useAuth must be used within AuthProvider");
118	  }
119	  return context;
120	}
