3	const CART_KEY = "hm_cart";
4	
5	export function useCart() {
6	  const [items, setItems] = useState(() => {
7	    const raw = localStorage.getItem(CART_KEY);
8	    return raw ? JSON.parse(raw) : [];
9	  });
10	
11	  useEffect(() => {
12	    localStorage.setItem(CART_KEY, JSON.stringify(items));
13	  }, [items]);
14	
15	  const api = useMemo(
16	    () => ({
17	      items,
18	      addItem(listing, quantity = 1) {
19	        setItems((prev) => {
20	          const existing = prev.find((item) => item.id === listing.id);
21	          if (existing) {
22	            return prev.map((item) =>
23	              item.id === listing.id
24	                ? { ...item, quantity: item.quantity + quantity }
25	                : item,
26	            );
27	          }
28	          return [
29	            ...prev,
30	            {
31	              id: listing.id,
32	              title: listing.title,
33	              price: listing.price,
34	              listing,
35	              quantity,
36	            },
37	          ];
38	        });
39	      },
40	      updateQuantity(id, quantity) {
41	        setItems((prev) =>
42	          prev.map((item) => (item.id === id ? { ...item, quantity } : item)),
43	        );
44	      },
45	      removeItem(id) {
46	        setItems((prev) => prev.filter((item) => item.id !== id));
47	      },
48	      clear() {
49	        setItems([]);
50	      },
51	    }),
52	    [items],
53	  );
54	
55	  return api;
56	}
