1	import { useEffect, useMemo, useState } from "react";
2	
3	export function useCountdown(targetDate) {
4	  const [now, setNow] = useState(Date.now());
5	
6	  useEffect(() => {
7	    const interval = setInterval(() => setNow(Date.now()), 1000);
8	    return () => clearInterval(interval);
9	  }, []);
10	
11	  return useMemo(() => {
12	    if (!targetDate) {
13	      return { expired: false, label: "--:--:--", ratio: 0 };
14	    }
15	
16	    const end = new Date(targetDate).getTime();
17	    const diff = Math.max(0, end - now);
18	    const expired = diff <= 0;
19	    const hours = Math.floor(diff / 3600000);
20	    const minutes = Math.floor((diff % 3600000) / 60000);
21	    const seconds = Math.floor((diff % 60000) / 1000);
22	
23	    const totalWindow = 24 * 3600000;
24	    const ratio = Math.max(0, Math.min(1, diff / totalWindow));
25	    const label = `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(
26	      seconds,
27	    ).padStart(2, "0")}`;
28	
29	    return { expired, label, ratio };
30	  }, [targetDate, now]);
31	}
