1	import axios from "axios";
2	import { getToken } from "../auth/tokenStore";
3	import { generateIdempotencyKey } from "../utils/idempotency";
4	
5	let unauthorizedHandler = null;
6	let rateLimitHandler = null;
7	
8	export function setUnauthorizedHandler(handler) {
9	  unauthorizedHandler = handler;
10	}
11	
12	export function setRateLimitHandler(handler) {
13	  rateLimitHandler = handler;
14	}
15	
16	const apiClient = axios.create({
17	  baseURL: import.meta.env.VITE_API_BASE_URL || "/api/v1",
18	  timeout: 20000,
19	});
20	
21	apiClient.interceptors.request.use((config) => {
22	  const token = getToken();
23	  if (token) {
24	    config.headers.Authorization = `Bearer ${token}`;
25	  }
26	
27	  const url = config.url || "";
28	  const method = (config.method || "get").toLowerCase();
29	  if (
30	    method === "post" &&
31	    (url.startsWith("/orders") || url.includes("/orders/")) &&
32	    !config.headers["X-Idempotency-Key"]
33	  ) {
34	    config.headers["X-Idempotency-Key"] = generateIdempotencyKey();
35	  }
36	
37	  return config;
38	});
39	
40	apiClient.interceptors.response.use(
41	  (response) => {
42	    if (response.config?.skipEnvelope) {
43	      return response;
44	    }
45	
46	    const payload = response.data;
47	    if (payload && typeof payload === "object" && "success" in payload) {
48	      if (!payload.success) {
49	        return Promise.reject(payload.error || { message: "Request failed" });
50	      }
51	      return payload.data;
52	    }
53	    return payload;
54	  },
55	  (error) => {
56	    const status = error?.response?.status;
57	    if (status === 401 && unauthorizedHandler) {
58	      unauthorizedHandler();
59	    }
60	
61	    if (status === 429 && rateLimitHandler) {
62	      const retryAfter = error?.response?.headers?.["retry-after"];
63	      rateLimitHandler(retryAfter || "60");
64	    }
65	
66	    const payload = error?.response?.data;
67	    if (payload?.error) {
68	      return Promise.reject(payload.error);
69	    }
70	
71	    return Promise.reject(error);
