              onClick={() => setMeta((prev) => ({ ...prev, page: prev.page - 1 }))}
            >
              Previous
            </Button>
            <span className="pagination-info">
              Page {meta.page + 1} of {meta.totalPages}
            </span>
            <Button
              variant="ghost"
              disabled={meta.page + 1 >= meta.totalPages}
              onClick={() => setMeta((prev) => ({ ...prev, page: prev.page + 1 }))}
            >
              Next
            </Button>
          </div>
        )}
      </section>"}

